public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending n-tersections are the same
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Check if the starting n-tersection is within the bounds of the n-teresting space
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
        return "cannot be travelled";
    }

    // Check if the ending n-tersection is within the bounds of the n-teresting space
    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Create a boolean array to track which n-tersections have been visited
    boolean[][] visited = new boolean[n][n];
    visited[start[0]][start[1]] = true;

    // Create a queue to store unvisited n-tersections
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Dequeue the next n-tersection
        int[] current = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Get the paths that connect to the current n-tersection
        int[][] pathsFromCurrent = paths[current[0]][current[1]];

        // Add unvisited paths to the queue
        for (int[] path : pathsFromCurrent) {
            if (!visited[path[0]][path[1]]) {
                queue.add(path);
                visited[path[0]][path[1]] = true;
            }
        }
    }

    // If the queue is empty, then no path can be found
    return "cannot be travelled";
}

