    // 1. Check if starting and ending coordinates are valid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
        throw new IllegalArgumentException("Invalid starting coordinates");
    }
    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        throw new IllegalArgumentException("Invalid ending coordinates");
    }

    // 2. Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n * n];
    Arrays.fill(visited, false);

    // 3. Initialize a queue to perform depth-first traversal of the n-teresting space
    Queue<Integer> queue = new ArrayDeque<>();
    queue.add(start[0] * n + start[1]);

    // 4. Continue traversal while there are still more n-tersections to visit
    while (!queue.isEmpty()) {
        int current = queue.remove();

        // 5. If the current n-tersection is the ending n-tersection, return true
        if (current == end[0] * n + end[1]) {
            return "can be travelled";
        }

        // 6. If the current n-tersection has already been visited, skip it
        if (visited[current]) {
            continue;
        }

        // 7. Mark the current n-tersection as visited and add its adjacent n-tersections to the queue
        visited[current] = true;
        for (int[] path : paths) {
            if (path[0] == current) {
                queue.add(path[1]);
            }
        }
    }

    // 8. If we reach this point, it means no path was found, return false
    return "cannot be travelled";
}

