    // Calculate the sum of all elements in the array
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // Calculate the average of the array
    double avg = sum / (double) nums.length;

    // Initialize a running sum with the first element
    int runningSum = nums[0];
    int runningCount = 1;

    // Iterate through the remaining elements and check if the running sum
    // is equal to the average after each element is added
    for (int i = 1; i < nums.length; i++) {
        int num = nums[i];
        runningSum += num;
        runningCount++;

        if (runningSum / (double) runningCount == avg) {
            return true;
        }
    }

    // If the sum is not equal to the average after iterating through all elements,
    // the array cannot be split into two arrays with the same average
    return false;
}

