    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("s cannot be null or empty");
    }

    // Check if k is less than 1
    if (k < 1) {
        throw new IllegalArgumentException("k must be greater than or equal to 1");
    }

    // Check if k is greater than the length of s
    if (k > s.length()) {
        return false;
    }

    // Initialize the set of all binary strings of length k
    Set<String> codes = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        codes.add(s.substring(i, i + k));
    }

    // Check if every binary string of length k is a substring of s
    for (int i = 0; i <= s.length() - k; i++) {
        if (!codes.contains(s.substring(i, i + k))) {
            return false;
        }
    }

    // All binary strings of length k are substrings of s, return true
    return true;
}

