    int insertions = 0; // Number of insertions.

    for (int i = 0; i < s.length(); i++) {
        // Check if the current character is a '('
        if (s.charAt(i) == '(') {
            balance++;
        } else { // Check if the current character is a ')'.
            balance--;

            // Check if there are more left brackets than rights.
            if (balance < 0) {
