public int minInsertions(String s) {
    int insertions = 0;
    Stack<Character> stack = new Stack<>();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            stack.push(c);
        } else if (c == ')') {
            if (stack.isEmpty()) {
                insertions++;
            } else {
                stack.pop();
            }
        } else {
            throw new IllegalArgumentException("Invalid character in string");
        }
    }
    while (!stack.isEmpty()) {
        insertions++;
        stack.pop();
    }
    return insertions;
}

