public static int minPerfectSquareSum(int n) {
    // keep track of the minimum number of perfect square numbers required
    int minNumberOfPerfectSquares = 0;

    // loop through all perfect squares until the sum reaches or exceeds n
    for (int i = 1; i * i <= n; i++) {
        // update the minimum number of perfect square numbers required
        minNumberOfPerfectSquares++;

        // check if the sum of the perfect squares is equal to n
        if (i * i == n) {
            // the sum is equal to n, so return the current number of perfect squares
            return minNumberOfPerfectSquares;
        }
    }

    // the sum has not reached n, so return the minimum number of perfect square numbers required
    return minNumberOfPerfectSquares;
}

